function SkillBar({ name, level, color }) {
  return (
    <div className="skill-bar">
      <div className="skill-bar__header">
        <span className="skill-bar__name">{name}</span>
        <span className="skill-bar__level" style={{ color }}>{level}%</span>
      </div>
      <div className="skill-bar__track">
        <div className="skill-bar__fill" style={{ '--fill-width': `${level}%`, '--fill-color': color }} />
      </div>
    </div>
  )
}

export default function Skills() {
  const [activeCategory, setActiveCategory] = useState(0)

  return (
    <section className="section skills" id="skills">
      <div className="skills__bg-glow" />
      <div className="container">
        <div className="reveal">
          <p className="section-label">My Toolkit</p>
          <h2 className="section-title">Technical <span className="gradient-text">Skills</span></h2>
        </div>

        {/* Tech pill band */}
        <div className="skills__orbit reveal" style={{ transitionDelay: '0.1s' }}>
          {techPills.map((tech, i) => (
            <div key={tech.name} className="skills__pill"
              style={{ '--pill-color': tech.color, animationDelay: `${i * 0.15}s` }}>
              {tech.name}
            </div>
          ))}
        </div>

        {/* Category tabs */}
        <div className="skills__tabs reveal" style={{ transitionDelay: '0.2s' }}>
          {skillCategories.map((cat, i) => (
            <button key={cat.label}
              className={`skills__tab ${activeCategory === i ? 'skills__tab--active' : ''}`}
              onClick={() => setActiveCategory(i)}>
              <span className="skills__tab-icon">{TAB_ICONS[cat.label]}</span>
              {cat.label}
            </button>
          ))}
        </div>

        {/* Skill bars */}
        <div className="skills__bars reveal" style={{ transitionDelay: '0.3s' }}>
          {skillCategories[activeCategory].skills.map(skill => (
            <SkillBar key={skill.name} {...skill} />
          ))}
        </div>

        {/* Also familiar with */}
        <div className="skills__all-tags reveal" style={{ transitionDelay: '0.4s' }}>
          <p className="skills__all-label">Also familiar with:</p>
          <div className="skills__tags">
            {['NoSQL', 'Postman', 'VS Code', 'Linux', 'Bash', 'HTML5', 'CSS3',
              'AI Model Integration', 'Web Scraping', 'STT/TTS', 'Image Recognition'].map(t => (
              <span className="tag" key={t}>{t}</span>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}
